<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Catalog\DTO\Request\QueueSyllabusProcessingRequestDto;use App\Application\Catalog\DTO\Response\SyllabusProcessingJobResponseDto;use App\Application\Catalog\Mapper\SyllabusProcessingJobResponseMapper;use App\Application\Catalog\Port\TransactionManagerInterface;use App\Domain\Catalog\Entity\SyllabusProcessingJob;use App\Domain\Catalog\Repository\SyllabusProcessingJobRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;
final class QueueSyllabusProcessingService { public function __construct(private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusProcessingJobRepositoryInterface $jobs,private readonly SyllabusProcessingJobResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function queue(QueueSyllabusProcessingRequestDto $input):SyllabusProcessingJobResponseDto{return $this->transactions->transactional(function()use($input){$syllabus=$this->syllabi->findById($input->syllabusId);if($syllabus===null||$syllabus->documentSha256===null)throw new \DomainException('O edital precisa possuir PDF.');$latest=$this->jobs->findLatestForSyllabus($syllabus->id);if(!$input->reprocess&&$latest!==null&&in_array($latest->status,['PENDING','PROCESSING','COMPLETED'],true)&&$latest->documentSha256===$syllabus->documentSha256)return $this->mapper->map($latest);$job=new SyllabusProcessingJob($this->uuid(),$syllabus->id,$syllabus->documentSha256,'PENDING',0,null,new \DateTimeImmutable('now'));$this->jobs->save($job);return $this->mapper->map($job);});} public function latest(string $syllabusId):?SyllabusProcessingJobResponseDto{$job=$this->jobs->findLatestForSyllabus($syllabusId);return $job===null?null:$this->mapper->map($job);} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
